(()=>{
const c=document.querySelector('#game'),g=c.getContext('2d'),W=1600,H=900,$=id=>document.getElementById(id),overlay=$('overlay'),keys={};
const bg=new Image();bg.src='data:image/png;base64,';
let state='menu',last=0,clock=90,score=0,hp=3,streak=0,delivered=0,carrying=false,shake=0,elapsed=0,toast='',toastT=0,sound=true,audio;
const drone={x:360,y:715,vx:0,vy:0,angle:-.2,inv:0};
const drop={x:1320,y:430};
const cargoSpots=[{x:500,y:420},{x:1050,y:280},{x:760,y:700},{x:1320,y:580},{x:290,y:540},{x:900,y:470}];
let cargo={...cargoSpots[0]},spotIndex=0,hazards=[],particles=[];
function tone(f=440,d=.12,type='sine'){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.value=f;v.gain.setValueAtTime(.04,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch(e){}}
function announce(t){toast=t;toastT=1.8}
function burst(x,y,col,n=22){for(let i=0;i<n;i++){let a=Math.random()*6.28,v=60+Math.random()*220;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.8,max:.8,col,r:2+Math.random()*4})}}
function hud(){$('score').textContent=String(score).padStart(5,'0');$('best').textContent='PERSONAL BEST '+String(Math.max(score,+(localStorage.neonBest||0))).padStart(5,'0');$('time').textContent=clock.toFixed(1)+'s';$('cargo').textContent=carrying?'SECURED':'EMPTY';$('cargo').style.color=carrying?'#c8ff67':'#40f4ff';$('cargoSub').textContent=carrying?'DELIVER TO DROP ZONE':'SEARCH FOR A BEACON';$('health').textContent='♥ '.repeat(hp).trim()||'—';$('health').style.color=hp===1?'#ff4d8e':'#c8ff67';$('streak').textContent='×'+streak;$('deliveries').textContent=delivered+' COMPLETED';$('log').textContent=delivered+' / 5 PACKAGES'}
function setup(){clock=90;score=0;hp=3;streak=0;delivered=0;carrying=false;spotIndex=0;cargo={...cargoSpots[0]};drone.x=360;drone.y=715;drone.vx=drone.vy=0;drone.inv=1.5;hazards=[{x:730,y:420,r:33,vx:55,vy:25},{x:1120,y:670,r:34,vx:-42,vy:35},{x:420,y:260,r:25,vx:35,vy:-30},{x:1370,y:280,r:29,vx:-32,vy:24}];particles=[];hud()}
function start(){setup();state='play';overlay.style.display='none';last=performance.now();requestAnimationFrame(loop);tone(620)}
function pause(){if(state==='play'){state='pause';show('FLIGHT PAUSED','Your drone is holding position. Resume the delivery contract when ready.','RESUME FLIGHT','RESTART');$('primaryBtn').onclick=resume;$('secondaryBtn').onclick=start}else if(state==='pause')resume()}
function resume(){state='play';overlay.style.display='none';last=performance.now();requestAnimationFrame(loop)}
function show(title,desc,primary,secondary){overlay.innerHTML=`<div class="dialog"><div class="symbol">✦</div><div class="eyebrow">VICE CITY // FLIGHT CONTROL</div><h2>${title}</h2><p>${desc}</p><div class="actions"><button class="primary" id="primaryBtn">${primary}</button>${secondary?`<button class="secondary" id="secondaryBtn">${secondary}</button>`:''}</div></div>`;overlay.style.display='flex'}
function finish(win){state='end';if(score>+(localStorage.neonBest||0))localStorage.neonBest=score;show(win?'VICE CITY <span>ACE</span>':'SHIFT <span>OVER</span>',win?'Five packages delivered. The city is counting on you, pilot. Outstanding work.':'Your shift has ended. Repair the drone and try for a higher delivery score.', 'PLAY AGAIN', '');$('primaryBtn').onclick=start;tone(win?880:160,.35,win?'sine':'sawtooth')}
function interact(){if(state!=='play')return;let target=carrying?drop:cargo;if(Math.hypot(drone.x-target.x,drone.y-target.y)>90){announce('MOVE CLOSER TO '+(carrying?'DROP ZONE':'CARGO'));tone(170,.1,'square');return}
if(!carrying){carrying=true;score+=25;burst(cargo.x,cargo.y,'#ff42d0');announce('PACKAGE ACQUIRED +25');$('status').textContent='CARGO MAGNETICALLY LOCKED';$('hint').textContent='Follow the cyan route marker to the SkyCargo drop zone.';tone(720); }
else{let bonus=150+Math.max(0,Math.floor(clock*2))+streak*25;score+=bonus;delivered++;streak++;carrying=false;burst(drop.x,drop.y,'#40f4ff',38);announce('DELIVERY COMPLETE +'+bonus);$('status').textContent='DROP CONFIRMED — CLIENT NOTIFIED';$('hint').textContent='Nice run. Find the next pink cargo beacon.';tone(850);if(delivered>=5){hud();finish(true);return}spotIndex=(spotIndex+1)%cargoSpots.length;cargo={...cargoSpots[spotIndex]};}hud()}
function collision(){if(drone.inv>0)return;hp--;streak=0;drone.inv=2;drone.vx*=-.55;drone.vy*=-.55;shake=.3;burst(drone.x,drone.y,'#ff477d');announce('TRAFFIC IMPACT // SHIELD DOWN');$('status').textContent='WARNING — COLLISION DETECTED';$('hint').textContent='Avoid moving traffic drones and street hazards.';tone(120,.25,'sawtooth');hud();if(hp<=0)finish(false)}
function loop(now){if(state!=='play')return;let dt=Math.min((now-last)/1000,.035);last=now;elapsed+=dt;clock-=dt;let ax=0,ay=0;if(keys.ArrowLeft||keys.a)ax--;if(keys.ArrowRight||keys.d)ax++;if(keys.ArrowUp||keys.w)ay--;if(keys.ArrowDown||keys.s)ay++;let boost=!!keys.Shift;let accel=boost?780:520,max=boost?350:250;drone.vx=(drone.vx+ax*accel*dt)*Math.pow(.92,dt*60);drone.vy=(drone.vy+ay*accel*dt)*Math.pow(.92,dt*60);if(boost)clock-=dt*.3;let m=Math.hypot(drone.vx,drone.vy);if(m>max){drone.vx=drone.vx/m*max;drone.vy=drone.vy/m*max}drone.x=Math.max(40,Math.min(W-40,drone.x+drone.vx*dt));drone.y=Math.max(40,Math.min(H-40,drone.y+drone.vy*dt));if(m>10)drone.angle=Math.atan2(drone.vy,drone.vx);drone.inv=Math.max(0,drone.inv-dt);
hazards.forEach(h=>{h.x+=h.vx*dt;h.y+=h.vy*dt;if(h.x<260||h.x>1450)h.vx*=-1;if(h.y<180||h.y>790)h.vy*=-1;if(Math.hypot(drone.x-h.x,drone.y-h.y)<h.r+23)collision()});particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy*=.98;p.life-=dt});toastT=Math.max(0,toastT-dt);shake=Math.max(0,shake-dt);draw();hud();if(clock<=0){finish(false);return}requestAnimationFrame(loop)}
function glow(x,y,r,color,alpha=.4){let gr=g.createRadialGradient(x,y,1,x,y,r);gr.addColorStop(0,color.replace(')',`,${alpha})`).replace('rgb','rgba'));gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.beginPath();g.arc(x,y,r,0,7);g.fill()}
function draw(){g.save();if(shake)g.translate((Math.random()-.5)*6,(Math.random()-.5)*6);if(bg.complete&&bg.naturalWidth)g.drawImage(bg,0,0,W,H);else{g.fillStyle='#17152e';g.fillRect(0,0,W,H)}
// subtle night tint keeps the uploaded artwork visible
g.fillStyle='rgba(9,8,34,.16)';g.fillRect(0,0,W,H);
// target path
let target=carrying?drop:cargo;g.save();g.strokeStyle=carrying?'rgba(64,244,255,.8)':'rgba(255,66,208,.8)';g.lineWidth=4;g.setLineDash([13,12]);g.beginPath();g.moveTo(drone.x,drone.y);g.lineTo(target.x,target.y);g.stroke();g.setLineDash([]);g.restore();
// drop pad
g.save();g.translate(drop.x,drop.y);g.shadowColor='#40f4ff';g.shadowBlur=35;g.strokeStyle='#40f4ff';g.lineWidth=6;g.beginPath();g.arc(0,0,56+Math.sin(elapsed*3)*5,0,7);g.stroke();g.shadowBlur=0;g.fillStyle='rgba(30,210,255,.18)';g.beginPath();g.arc(0,0,44,0,7);g.fill();g.strokeStyle='#d7ffff';g.lineWidth=3;g.beginPath();g.moveTo(-22,0);g.lineTo(22,0);g.moveTo(0,-22);g.lineTo(0,22);g.stroke();g.fillStyle='#d7ffff';g.font='bold 17px Orbitron';g.textAlign='center';g.fillText('DROP',0,85);g.restore();
// cargo marker
if(!carrying){g.save();g.translate(cargo.x,cargo.y);let pulse=1+Math.sin(elapsed*5)*.12;g.shadowColor='#ff42d0';g.shadowBlur=30;g.strokeStyle='#ff65df';g.lineWidth=5;g.beginPath();g.arc(0,0,32*pulse,0,7);g.stroke();g.fillStyle='#ff42d0';g.fillRect(-12,-12,24,24);g.shadowBlur=0;g.fillStyle='#fff';g.font='bold 15px Orbitron';g.textAlign='center';g.fillText('CARGO',0,-49);g.restore()}
// traffic hazards
hazards.forEach(h=>{g.save();g.translate(h.x,h.y);g.rotate(elapsed);g.shadowColor='#ff326b';g.shadowBlur=20;g.strokeStyle='#ff5b91';g.lineWidth=4;g.beginPath();g.arc(0,0,h.r,0,7);g.stroke();g.beginPath();g.moveTo(-h.r*.65,-h.r*.65);g.lineTo(h.r*.65,h.r*.65);g.moveTo(h.r*.65,-h.r*.65);g.lineTo(-h.r*.65,h.r*.65);g.stroke();g.restore()});
// drone
g.save();g.translate(drone.x,drone.y);g.rotate(drone.angle);g.globalAlpha=drone.inv>0&&Math.floor(elapsed*12)%2===0?.35:1;g.shadowColor='#40f4ff';g.shadowBlur=24;g.strokeStyle='#42eaff';g.lineWidth=7;[[-26,-22],[26,-22],[-26,22],[26,22]].forEach(([x,y])=>{g.beginPath();g.moveTo(0,0);g.lineTo(x,y);g.stroke();g.beginPath();g.ellipse(x,y,19,6,elapsed*4,0,7);g.stroke()});g.fillStyle='#ffb8ef';g.strokeStyle='#fff';g.lineWidth=2;g.beginPath();g.roundRect(-20,-14,40,28,8);g.fill();g.stroke();g.fillStyle='#15294b';g.beginPath();g.arc(7,0,7,0,7);g.fill();if(carrying){g.fillStyle='#c8ff67';g.fillRect(-9,22,18,17)}g.restore();
particles.forEach(p=>{g.globalAlpha=Math.max(0,p.life/p.max);g.fillStyle=p.col;g.beginPath();g.arc(p.x,p.y,p.r,0,7);g.fill()});g.globalAlpha=1;
// minimap and live toast
g.fillStyle='rgba(4,8,25,.75)';g.fillRect(28,28,225,62);g.strokeStyle='#40f4ff';g.strokeRect(28,28,225,62);g.fillStyle='#40f4ff';g.font='bold 15px Orbitron';g.fillText('VICE CITY // GPS',42,53);g.fillStyle='#d6e9ff';g.font='13px Rajdhani';g.fillText('AIR UNIT: ONLINE',42,76);
// Open-world style mission HUD: cash, wanted-style alert meter, minimap and speed.
g.fillStyle='rgba(5,7,15,.78)';g.fillRect(1270,28,300,100);g.strokeStyle='rgba(255,106,157,.85)';g.strokeRect(1270,28,300,100);
g.textAlign='right';g.fillStyle='#9dff91';g.font='bold 25px Orbitron';g.fillText('$'+String(score).padStart(6,'0'),1548,61);
g.fillStyle='#f4f1f4';g.font='bold 20px Arial';g.fillText('✦ '.repeat(Math.max(0,Math.min(5,Math.ceil((3-hp)*1.6)))),1548,94);
g.fillStyle='#aeb8c8';g.font='12px Orbitron';g.fillText('DRONE ALERT',1548,116);
// Compact street-map radar.
g.fillStyle='rgba(5,8,17,.82)';g.fillRect(28,690,235,180);g.strokeStyle='rgba(98,232,255,.85)';g.strokeRect(28,690,235,180);
g.save();g.beginPath();g.rect(35,697,221,166);g.clip();g.strokeStyle='rgba(186,198,211,.42)';g.lineWidth=7;
for(let x=50;x<260;x+=42){g.beginPath();g.moveTo(x,700);g.lineTo(x+12,865);g.stroke()}for(let y=710;y<870;y+=37){g.beginPath();g.moveTo(35,y);g.lineTo(255,y-9);g.stroke()}
g.strokeStyle='#ff6a9d';g.lineWidth=4;g.beginPath();g.moveTo(drone.x/1600*220+35,drone.y/900*165+697);g.lineTo(target.x/1600*220+35,target.y/900*165+697);g.stroke();g.fillStyle='#fff';g.beginPath();g.arc(drone.x/1600*220+35,drone.y/900*165+697,6,0,7);g.fill();g.fillStyle='#ff6a9d';g.beginPath();g.arc(target.x/1600*220+35,target.y/900*165+697,6,0,7);g.fill();g.restore();
g.fillStyle='rgba(5,7,15,.78)';g.fillRect(1320,790,250,78);g.strokeStyle='rgba(98,232,255,.8)';g.strokeRect(1320,790,250,78);g.textAlign='right';g.fillStyle='#62e8ff';g.font='bold 30px Orbitron';g.fillText(Math.round(Math.hypot(drone.vx,drone.vy)*.32)+'',1548,829);g.fillStyle='#d9dce5';g.font='12px Orbitron';g.fillText('KM/H  //  AIR SPEED',1548,851);
// Contract objective banner.
g.fillStyle='rgba(5,7,15,.72)';g.fillRect(545,28,510,54);g.strokeStyle='rgba(255,106,157,.72)';g.strokeRect(545,28,510,54);g.textAlign='center';g.fillStyle='#ff8bb1';g.font='bold 15px Orbitron';g.fillText(carrying?'CONTRACT: DELIVER PRIORITY CARGO':'CONTRACT: LOCATE PRIORITY CARGO',800,51);g.fillStyle='#e7e4ed';g.font='13px Rajdhani';g.fillText(carrying?'ROOFTOP DROP ZONE MARKED ON GPS':'PICK UP THE PACKAGE TO START DELIVERY',800,70);
if(toastT>0){g.fillStyle='rgba(8,8,27,.85)';g.fillRect(570,35,460,48);g.strokeStyle='#ff42d0';g.strokeRect(570,35,460,48);g.fillStyle='#ff8be8';g.font='bold 18px Orbitron';g.textAlign='center';g.fillText(toast,800,66)}g.restore()}
window.addEventListener('keydown',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[k]=true;if(e.code==='Space'&&!e.repeat)interact();if((k==='p'||k==='Escape')&&!e.repeat)pause()});window.addEventListener('keyup',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;keys[k]=false});
$('start').onclick=start;$('how').onclick=()=>show('HOW TO <span>PLAY</span>','Move with WASD or arrow keys. Fly close to the pink cargo beacon and press SPACE to pick it up. Carry it to the cyan drop zone and press SPACE again. Avoid red traffic hazards. Hold SHIFT to boost, but boost drains extra time.','GOT IT — START','');$('primaryBtn')?.addEventListener('click',start);
$('mAction').onclick=interact;$('mBoost').onpointerdown=()=>keys.Shift=true;$('mBoost').onpointerup=()=>keys.Shift=false;document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key,down=e=>{e.preventDefault();keys[k]=true},up=e=>{e.preventDefault();keys[k]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up)});
draw();hud();
})();
